CREATE TABLE users(id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE TABLE purchases(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, product TEXT NOT NULL, merchant TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT 'Electronics', purchase_date TEXT, delivery_date TEXT, price_minor INTEGER, currency TEXT NOT NULL DEFAULT 'INR', order_ref TEXT NOT NULL DEFAULT '', serial TEXT NOT NULL DEFAULT '', confirmed INTEGER NOT NULL DEFAULT 0, sample INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE documents(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), purchase_id TEXT NOT NULL REFERENCES purchases(id) ON DELETE CASCADE, type TEXT NOT NULL, name TEXT NOT NULL, storage_key TEXT NOT NULL, mime TEXT NOT NULL, byte_size INTEGER NOT NULL, hash TEXT NOT NULL, state TEXT NOT NULL, text TEXT NOT NULL DEFAULT '', method TEXT NOT NULL DEFAULT '', error TEXT, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(purchase_id,type,hash));
CREATE TABLE passages(id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE, purchase_id TEXT NOT NULL REFERENCES purchases(id) ON DELETE CASCADE, page INTEGER NOT NULL, excerpt TEXT NOT NULL, kind TEXT NOT NULL, version INTEGER NOT NULL);
CREATE TABLE deadlines(id TEXT PRIMARY KEY, purchase_id TEXT NOT NULL REFERENCES purchases(id) ON DELETE CASCADE, passage_id TEXT NOT NULL REFERENCES passages(id) ON DELETE CASCADE, kind TEXT NOT NULL, trigger TEXT NOT NULL, trigger_date TEXT NOT NULL, period INTEGER, unit TEXT, deadline TEXT NOT NULL, assumptions TEXT NOT NULL, confirmed INTEGER NOT NULL DEFAULT 1);
CREATE TABLE cases(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), purchase_id TEXT NOT NULL REFERENCES purchases(id) ON DELETE CASCADE, idempotency_key TEXT NOT NULL, issue TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', checklist TEXT NOT NULL, draft TEXT NOT NULL, citations TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(owner_id,idempotency_key));
CREATE TABLE conversations(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), purchase_id TEXT REFERENCES purchases(id) ON DELETE SET NULL, case_id TEXT REFERENCES cases(id) ON DELETE SET NULL, created_at TEXT NOT NULL);
CREATE TABLE messages(seq INTEGER PRIMARY KEY AUTOINCREMENT, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, role TEXT NOT NULL, text TEXT NOT NULL, citations TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL);
CREATE TABLE events(id INTEGER PRIMARY KEY AUTOINCREMENT, case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE, type TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX purchases_owner ON purchases(owner_id);
CREATE INDEX conversations_owner ON conversations(owner_id);
CREATE INDEX messages_order ON messages(conversation_id,seq);
